			{SessionID: "secret-sess", Branch: "main", Agent: "claude", LatestCheckpoint: "cp2", TranscriptPath: secret, CreatedAt: now.Add(-time.Hour)},
		}}},
	}
	if err := writeBrainManifestAndReadme(brainDir, manifest); err != nil {
		t.Fatal(err)
